struct nglListNode;

template<class T1, class T2>
struct pair {
    T1 first;
    T2 second;
};

struct nglTransCompare {
    bool operator()(
        const pair<nglListNode *, unsigned int> &left,
        const pair<nglListNode *, unsigned int> &right) const
    {
        if (reinterpret_cast<const float &>(left.second) >
            reinterpret_cast<const float &>(right.second))
            return true;
        if (reinterpret_cast<const float &>(left.second) <
            reinterpret_cast<const float &>(right.second))
            return false;
        return left.first < right.first;
    }
};

template<class BidirectionalIter>
BidirectionalIter copy_backward(
    BidirectionalIter first,
    BidirectionalIter last,
    BidirectionalIter result)
{
    while (first != last)
        *--result = *--last;
    return result;
}

template<class RandomAccessIter, class T, class Compare>
inline void __linear_insert(
    RandomAccessIter first,
    RandomAccessIter last,
    T *,
    Compare comp)
{
    T value = *last;
    if (comp(value, *first)) {
        copy_backward(first, last, last + 1);
        *first = value;
    }
    else
        __unguarded_linear_insert(last, value, comp);
}

template<class RandomAccessIter, class Compare>
void __insertion_sort(
    RandomAccessIter first,
    RandomAccessIter last,
    Compare comp)
{
    if (first == last)
        return;
    for (RandomAccessIter i = first + 1; i != last; ++i)
        __linear_insert(first, i, (pair<nglListNode *, unsigned int> *)0, comp);
}

template void __insertion_sort(
    pair<nglListNode *, unsigned int> *,
    pair<nglListNode *, unsigned int> *,
    nglTransCompare);
